74:// interruptOnDone sets up a goroutine to interrupt the provided db when the
75:// context is canceled, and returns a function the caller must defer so it
76:// doesn't interrupt after the caller finishes.
77:func interruptOnDone(
78:	ctx context.Context,
79:	c *conn,
80:	done *int32,
81:) func() {
82:	if done == nil {
83:		var d int32
84:		done = &d
85:	}
86:	// donemu prevents a TOCTOU logical race between checking the done flag and
87:	// calling interrupt in the select statement below.
88:	var donemu sync.Mutex
89:
90:	donech := make(chan struct{})
91:
92:	go func() {
93:		select {
94:		case <-ctx.Done():
95:			// don't call interrupt if we were already done: it indicates that this
96:			// call to exec is no longer running and we would be interrupting
97:			// nothing, or even possibly an unrelated later call to exec.
98:			donemu.Lock()
99:			if atomic.CompareAndSwapInt32(done, 0, 1) {
100:				c.interrupt(c.db)
101:			}
102:			donemu.Unlock()
103:		case <-donech:
104:		}
105:	}()
106:
107:	// the caller is expected to defer this function
108:	return func() {
109:		// set the done flag so that a context cancellation right after the caller
110:		// returns doesn't trigger a call to interrupt for some other statement.
111:		donemu.Lock()
112:		atomic.StoreInt32(done, 1)
113:		donemu.Unlock()
114:		close(donech)
115:	}
116:}
